# Read a login flow out of a HAR file: the redirect chain, and the code or SAMLResponse where it appears
import json, base64, urllib.parse
har = json.load(open("login.har"))
for e in har["log"]["entries"]:
    req, res = e["request"], e["response"]
    print(res["status"], req["method"], req["url"][:90])
    for h in res.get("headers", []):
        if h["name"].lower() == "location":
            print("   ->", h["value"][:120])
    if req["method"] == "POST":
        for p in req.get("postData", {}).get("params", []):
            if p["name"] == "SAMLResponse":
                xml = base64.b64decode(urllib.parse.unquote(p["value"])).decode()
                print("   SAMLResponse:", xml[:200])
# the OIDC code is in the Location header of the IdP's final redirect (?code=...&state=...); never paste either into a public tool
